// Parse and format incoming payload
const body = $input.item.json.body || $input.item.json;
return [{
  json: {
    trace_id: body.trace_id || 'UNKNOWN',
    session_id: body.session_id || 'unknown_session',
    reason: body.reason || 'User requested human escalation',
    user_message: body.user_message || body.payload?.user_message || '',
    route_taken: body.route_taken || 'escalated',
    confidence_score: typeof body.confidence_score === 'number' ? body.confidence_score : 0.2,
    received_at: new Date().toISOString()
  }
}];

const data = $input.item.json;
const ticketNum = Math.floor(1000 + Math.random() * 9000);
return [{
  json: {
    ticket_id: `TICK-ESC-${ticketNum}`,
    status: 'OPEN',
    priority: data.confidence_score < 0.3 ? 'URGENT' : 'HIGH',
    assigned_department: 'Tier-2 Human Support Lead',
    trace_id: data.trace_id,
    reason: data.reason,
    user_inquiry: data.user_message,
    created_at: new Date().toISOString()
  }
}];

const ticket = $input.item.json;
console.log(`[SLACK/EMAIL NOTIFICATION SENT] To: support-alerts@company.internal | Ticket: ${ticket.ticket_id} | Trace: ${ticket.trace_id} | Priority: ${ticket.priority}`);
return [{
  json: {
    notification_sent: true,
    channel: '#support-escalations',
    recipient: 'support-alerts@company.internal',
    ...ticket
  }
}];
